// radio_golden_2025_may_afternoon.js — Radiology 12 May Afternoon 2025 paper (152 source + 2 from continuation image = 154 total)
// Schema: {q,o,a,e} with 5 options A-E and answer index 0-4
// Explanation: P1 mechanism + Take Notes discriminator chain (target ~50 words total)
if(!window.MM) window.MM={};
window.MM['radio_golden_2025_may_afternoon']=[
/*1*/ {"q":"Myocardial infarction — which artery is most commonly involved?","o":["Left anterior descending artery","Left coronary artery","Right Coronary artery","Posterior descending artery","Circumflex artery"],"a":0,"e":"The left anterior descending artery (LAD) is the most commonly occluded artery in MI (40-50%); supplies anterior wall, anterior 2/3 of interventricular septum, and apex of left ventricle.<br><br>Take Notes: RCA → inferior wall (II, III, aVF) | LCX → lateral wall | LAD = most common MI (widow-maker)."},
/*2*/ {"q":"Myxoid degeneration associated with:","o":["Mitral valve prolapse","Libman-Sacks endocarditis","Marantic endocarditis","Infective endocarditis","Neoplasm"],"a":0,"e":"Mitral valve prolapse (MVP) shows myxomatous (myxoid) degeneration of valve leaflets with accumulation of proteoglycan-rich ground substance; floppy ballooning leaflets cause mid-systolic click and late systolic murmur.<br><br>Take Notes: Libman-Sacks → SLE | Marantic → cancer-related | Myxoid degeneration = mitral valve prolapse (Robbins + Kaplan)."},
/*3*/ {"q":"A patient presents with exertional chest pain relieved by rest. Most appropriate initial diagnostic test to confirm the diagnosis?","o":["Exercise stress test","Coronary angiography","X-ray","Echocardiography","Cardiac MRI"],"a":0,"e":"Exertional chest pain relieved by rest suggests stable angina; exercise stress test is the initial non-invasive test to demonstrate inducible ischemia via ECG changes during graded exercise.<br><br>Take Notes: Coronary angio → definitive but invasive | Echo → wall motion | Stable angina initial = exercise stress test."},
/*4*/ {"q":"Atherosclerotic plaque has which 3 principal components?","o":["Smooth muscle, T cells, neutrophils","Smooth muscle, lymphocytes","Lymphocytes only","Smooth muscle, macrophages, T cells with extracellular matrix and intracellular lipids","Foam cells and cholesterol clefts"],"a":3,"e":"Robbins triad of atherosclerotic plaque: cells (smooth muscle, macrophages/foam cells, T lymphocytes), extracellular matrix (collagen, elastic fibers, proteoglycans), and intra/extracellular lipids.<br><br>Take Notes: Foam cells = lipid-laden macrophages | 3 components = cells + ECM + lipids = Robbins."},
/*5*/ {"q":"Type of fluid due to CHF is:","o":["Exudate","Transudate","Serous","Fibrinous","Purulent"],"a":1,"e":"Congestive heart failure causes pure hydrostatic edema: low protein content, low specific gravity, low cell count — classic transudate. Increased venous pressure drives plasma ultrafiltrate into interstitium.<br><br>Take Notes: Exudate → inflammation, high protein | Transudate → pure pressure-driven | CHF effusion = transudate."},
/*6*/ {"q":"A patient has intermittent dysphagia with GERD. Barium swallow showed dilated oesophagus with tapered end (bird-beak appearance), air-fluid levels noted on X-ray. Diagnosis?","o":["Achalasia cardia","GERD","Esophagitis","Diffuse oesophageal spasm","Failure of LES to relax"],"a":0,"e":"Achalasia cardia: failure of LES relaxation and loss of esophageal peristalsis. Barium swallow shows characteristic \"bird-beak\" tapering at LES with proximal dilatation and air-fluid levels.<br><br>Take Notes: GERD → no bird-beak | Diffuse spasm → corkscrew | Bird-beak + dilated esophagus = achalasia."},
/*7*/ {"q":"A patient presents with abdominal pain and bloody diarrhea. Colonoscopy reveals cobblestone mucosa and skip lesions. Most likely diagnosis?","o":["Crohn's disease","Ulcerative colitis","Infectious colitis","Ischemic colitis","Irritable bowel syndrome"],"a":0,"e":"Crohn disease: transmural inflammation with discontinuous skip lesions and cobblestone mucosal appearance from linear ulcers crossing edematous mucosa; any GI segment from mouth to anus.<br><br>Take Notes: UC → continuous, rectum + mucosal only | Skip lesions + cobblestone = Crohn disease."},
/*8*/ {"q":"Maximum number of beta cells in islets of Langerhans are present in:","o":["Neck of pancreas","Tail of pancreas","Head of pancreas","Ampulla of Vater","Body of pancreas"],"a":1,"e":"The tail of pancreas contains the highest density of islets of Langerhans with most beta (insulin-producing) cells. Distal pancreatectomy carries diabetes risk due to beta cell loss.<br><br>Take Notes: Head = exocrine predominant | Body/neck = intermediate | Maximum beta cells = tail of pancreas."},
/*9*/ {"q":"A patient is diagnosed with a mutation in the ATP7B gene. Mode of inheritance?","o":["Autosomal recessive","Autosomal dominant","X-linked recessive","Mitochondrial inheritance","Y-linked inheritance"],"a":0,"e":"Wilson disease: autosomal recessive ATP7B gene mutation impairs hepatic copper excretion, leading to copper accumulation in liver, brain (basal ganglia), and Kayser-Fleischer rings in cornea.<br><br>Take Notes: AD → Huntington, NF | X-linked → hemophilia | ATP7B mutation = Wilson disease (AR)."},
/*10*/ {"q":"Diagnosis of colon CA made many years back, CEA was raised that time. Patient came for regular checkup. What is role of CEA now?","o":["For staging","For follow up","To confirm malignancy","Cell differentiation","Screening"],"a":1,"e":"After cancer diagnosis and treatment, CEA is used for follow-up to detect recurrence; baseline elevated CEA that normalises then rises again indicates relapse. Not for staging or initial diagnosis.<br><br>Take Notes: Staging → CT/imaging | Confirm malignancy → biopsy | Post-treatment CEA = follow-up for recurrence."},
/*11*/ {"q":"A patient's 100 cm of ileum was resected. Which vitamin is needed for supplementation?","o":["Vitamin C","Vitamin K","Vitamin B12","Vitamin B6","Folate"],"a":2,"e":"Distal (terminal) ileum is the exclusive site of vitamin B12 absorption via intrinsic factor receptors; >100 cm ileal resection causes B12 deficiency. Lifetime parenteral B12 supplementation needed.<br><br>Take Notes: Folate → proximal jejunum | Vitamin K → bacterial synthesis | Ileal resection = B12 deficiency."},
/*12*/ {"q":"Pure mucinous glands are:","o":["Submandibular","Sublingual","Parotid","Adrenal glands","Pineal glands"],"a":1,"e":"Sublingual glands are predominantly mucous (mucinous) secreting. Submandibular = mixed (serous>mucous), parotid = pure serous. Mucous secretions are viscous and protective.<br><br>Take Notes: Parotid → pure serous | Submandibular → mixed | Pure mucinous gland = sublingual."},
/*13*/ {"q":"A patient is diagnosed with active hepatitis B infection. Which of the following serological markers typically indicates active infection that requires treatment?","o":["HBsAg positive and HBeAg positive","HBsAg positive and anti-HBe positive","Anti-HBs positive and anti-HBc positive","IgG positive","Anti-HBs positive only"],"a":0,"e":"HBsAg + HBeAg positive indicates active replicating Hepatitis B with high infectivity and viral load; treatment is indicated. HBeAg seroconversion to anti-HBe marks reduced replication.<br><br>Take Notes: Anti-HBs → immunity/vaccination | Anti-HBc IgM → acute | HBsAg + HBeAg = active replicating HBV."},
/*14*/ {"q":"If root of left lung is injured, which structure will be spared?","o":["Pulmonary ligament","Pulmonary artery","Pulmonary vein","Bronchus","Vagus nerve"],"a":4,"e":"The vagus nerve passes posterior to the lung root (not within it), so root injury spares the vagus nerve. Pulmonary artery, veins, and bronchus lie within the root.<br><br>Take Notes: Phrenic → anterior to root | Root = PA + PV + bronchus | Vagus = posterior, spared."},
/*15*/ {"q":"A footballer developed sudden chest pain. O/E stony dull percussion note on right side of chest and trachea deviated to left side. Cause?","o":["Left sided pneumothorax","Left sided pleural effusion","Right sided pneumothorax","Right sided pleural effusion","Hemothorax"],"a":3,"e":"Stony dull percussion indicates fluid (effusion) not air (pneumothorax). Tracheal deviation to opposite (left) side indicates large right-sided effusion pushing mediastinum.<br><br>Take Notes: Pneumothorax → hyperresonant percussion | Tension → trachea away from lesion | Stony dull + away deviation = pleural effusion (right)."},
/*16*/ {"q":"Thoracocentesis at 9th intercostal space — most likely damaged is:","o":["Glossopharyngeal nerve","Diaphragm","Percardiophrenic artery","9th intercostal artery","10th intercostal nerve"],"a":1,"e":"Below the 8th-9th intercostal space (in mid-axillary line), the needle risks puncturing the diaphragm and may damage abdominal organs (liver on right, spleen on left). Safe zone is 7th-8th space.<br><br>Take Notes: Above 7th → risk of axillary structures | Below 9th → risk of diaphragm | 9th ICS thoracocentesis = diaphragm injury."},
/*17*/ {"q":"True about fat embolism:","o":["Can occur before 12 hours","Almost 80% fatal","Common cause of thrombophlebitis","Breast trauma","Severe injury to skeletal system"],"a":4,"e":"Fat embolism syndrome typically follows long bone fractures or severe trauma to skeletal system. Onset is delayed 24-72 hours after injury. Presents with pulmonary, neurological, and skin signs.<br><br>Take Notes: Onset 1-3 days (not <12h) | Mortality ~10-20% (not 80%) | Fat embolism cause = severe skeletal injury."},
/*18*/ {"q":"A patient presents with symptoms of Goodpasture syndrome. Which antibody is most commonly associated with this condition?","o":["Anti-glomerular basement membrane (anti-GBM) antibodies","Anti-nuclear antibodies (ANA)","Anti-neutrophil cytoplasmic antibodies (ANCA)","Rheumatoid factor (RF)","Anti-double stranded DNA antibodies"],"a":0,"e":"Goodpasture syndrome: autoantibodies (anti-GBM) target type IV collagen α3 chain in glomerular and alveolar basement membranes, causing hematuria with hemoptysis (pulmonary-renal syndrome). Linear IgG deposition on biopsy.<br><br>Take Notes: ANCA → vasculitis | ANA → SLE | Anti-dsDNA → SLE specific | Goodpasture = anti-GBM antibodies."},
/*19*/ {"q":"How is microalbuminuria screened in a patient with diabetes mellitus?","o":["Spot urine albumin-to-creatinine ratio","Urine for creatinine","Dipstick urine test","24-hour urine collection","Serum albumin"],"a":0,"e":"Spot urine albumin-to-creatinine ratio (ACR) is the screening test for diabetic microalbuminuria; convenient, doesn't require 24-hour collection, and accounts for urine concentration variations.<br><br>Take Notes: Dipstick → misses microalbuminuria | 24h collection → gold standard but cumbersome | Diabetic screen = spot ACR."},
/*20*/ {"q":"A child presents with pedal edema and urine analysis shows 3+ proteinuria. What is the most likely diagnosis?","o":["Minimal change disease","Focal segmental glomerulosclerosis","Membranous nephropathy","Acute glomerulonephritis","IgA nephropathy"],"a":0,"e":"Minimal change disease (MCD) is the most common cause of nephrotic syndrome in children (>90%); presents with selective proteinuria, hypoalbuminemia, edema, hypercholesterolemia. Excellent response to steroids.<br><br>Take Notes: FSGS → African Americans, adults | Membranous → adults | Child + nephrotic = minimal change disease."},
/*21*/ {"q":"Effect of efferent arteriole dilation in renal physiology:","o":["Afferent arteriolar dilation","Efferent arteriolar dilation","Decrease plasma proteins","Afferent arteriolar constriction","Decrease GFR"],"a":1,"e":"Efferent arteriolar dilation reduces glomerular hydrostatic pressure, lowering GFR. Conversely, efferent constriction (e.g., by angiotensin II) increases hydrostatic pressure and GFR.<br><br>Take Notes: Afferent dilation → increases GFR | Efferent constriction → increases GFR | Efferent dilation = decreased GFR."},
/*22*/ {"q":"In hypotonic fluid, where is the fluid found in this part of nephron?","o":["DCT","Early PCT","Early LOH","CD","Thick limb"],"a":4,"e":"In the thick ascending limb of loop of Henle, Na+/K+/2Cl- co-transporter actively reabsorbs solute without water (impermeable to water), creating hypotonic tubular fluid (\"diluting segment\").<br><br>Take Notes: PCT → isotonic | DCT → variable | CD → ADH-controlled | Hypotonic fluid = thick ascending limb (TAL)."},
/*23*/ {"q":"GFR is measured by:","o":["Inulin","Creatinine","PAH","Ammonia","Urea"],"a":0,"e":"Inulin is the gold standard for measuring GFR — freely filtered, neither reabsorbed nor secreted. PAH measures renal plasma flow. Creatinine clearance approximates GFR clinically.<br><br>Take Notes: PAH → renal plasma flow | Creatinine → clinical GFR estimate | Inulin = gold standard GFR."},
/*24*/ {"q":"In a patient with diabetic ketoacidosis (DKA) presenting with diarrhoea, ABGs reveal a pH of 6.79. Initial management should include:","o":["Isotonic saline (0.9% NaCl) infusion plus insulin therapy","Sodium bicarbonate (NaHCO3) administration plus insulin therapy","Hypotonic saline solution plus insulin therapy","Oral rehydration solution and withholding insulin until diarrhoea stops","Glucose plus insulin"],"a":0,"e":"DKA management: isotonic saline (0.9% NaCl) for fluid resuscitation plus IV insulin to suppress ketogenesis. Bicarbonate reserved for severe acidosis (pH<6.9) and not first-line.<br><br>Take Notes: Bicarbonate → pH<6.9 only | Hypotonic later for free water deficit | DKA initial = NS + insulin."},
/*25*/ {"q":"Severe diarrhea leads to:","o":["Metabolic acidosis with normal anion gap","Metabolic acidosis with high anion gap","Metabolic acidosis with low anion gap","Metabolic alkalosis","Respiratory alkalosis"],"a":0,"e":"Severe diarrhea causes loss of bicarbonate (and Cl- gain), resulting in normal anion gap (hyperchloremic) metabolic acidosis. Contrasts with high anion gap acidosis from acid gain (DKA, lactic).<br><br>Take Notes: DKA/lactic → high anion gap | Diarrhea → bicarbonate loss + Cl- gain | Diarrhea = normal anion gap acidosis."},
/*26*/ {"q":"Persistent vomiting will lead to:","o":["Metabolic acidosis","Metabolic alkalosis","Respiratory alkalosis","Respiratory acidosis","Mixed acid-base"],"a":1,"e":"Persistent vomiting loses gastric HCl and chloride, causing hypochloremic, hypokalemic metabolic alkalosis. Compensatory renal H+ retention worsens alkalosis. Common in pyloric stenosis.<br><br>Take Notes: Diarrhea → metabolic acidosis | Vomiting → HCl loss | Persistent vomiting = metabolic alkalosis."},
/*27*/ {"q":"On microscopy, minimal change disease shows:","o":["Increased mesangial deposition","Effacement of podocyte foot processes","Sclerosis of glomerular capillaries","Crescent formation","Linear IgG deposition"],"a":1,"e":"Minimal change disease: light microscopy is normal (\"minimal change\"); electron microscopy shows effacement (fusion) of podocyte foot processes — the only abnormal finding. Immunofluorescence is negative.<br><br>Take Notes: Crescents → RPGN | Linear IgG → Goodpasture | Mesangial deposits → IgA | MCD EM = podocyte foot process effacement."},
/*28*/ {"q":"A 64-year-old female with fatigue, easy bruising after small cuts, and recurrent infection with fever for 2 weeks. After investigations, the report shows blast cells and Auer bodies in smear. Most likely diagnosis?","o":["Acute promyelocytic leukemia","Acute lymphoblastic leukemia","Acute myeloid leukemia","Non-Hodgkin lymphoma","Aplastic anemia"],"a":2,"e":"AML: bone marrow blasts >20%, Auer rods (peroxidase-positive azurophilic crystals) pathognomonic. Adults present with pancytopenia symptoms (fatigue, bleeding, infection). Auer rods are specific for AML.<br><br>Take Notes: APL (M3) → specific Auer rods variant + DIC | ALL → no Auer rods, TdT+ | Auer rods + blast cells = AML."},
/*29*/ {"q":"A patient with Hodgkin lymphoma is receiving chemotherapy. Which of the following drugs is most commonly associated with causing blood in the urine?","o":["Cyclophosphamide","Doxorubicin","Vincristine","Bleomycin","Prednisone"],"a":0,"e":"Cyclophosphamide metabolite acrolein damages bladder urothelium causing hemorrhagic cystitis with hematuria. Prevented with mesna (binds acrolein) and adequate hydration.<br><br>Take Notes: Doxorubicin → cardiotoxicity | Bleomycin → pulmonary fibrosis | Vincristine → neuropathy | Hemorrhagic cystitis = cyclophosphamide."},
/*30*/ {"q":"Which lymphoma is characterized by a \"starry sky\" appearance on histopathology?","o":["Mantle cell lymphoma","Diffuse large B-cell lymphoma","Burkitt lymphoma","Follicular lymphoma","Hodgkin lymphoma"],"a":2,"e":"Burkitt lymphoma: \"starry sky\" appearance from interspersed macrophages (tingible body macrophages clearing apoptotic debris) among sheets of dark neoplastic B cells. EBV-associated; t(8;14) c-MYC translocation.<br><br>Take Notes: Hodgkin → Reed-Sternberg cells | DLBCL → diffuse sheets | Starry sky = Burkitt lymphoma."},
/*31*/ {"q":"A patient receiving a blood transfusion develops chills and rigors. What is the immediate next step?","o":["Stop the transfusion and notify the blood bank","Slow down the transfusion rate and observe","Administer antihistamines and continue transfusion","Give intravenous fluids and continue transfusion","Administer corticosteroids and continue transfusion"],"a":0,"e":"Any transfusion reaction (chills, rigors, fever, hypotension) requires immediate transfusion cessation to prevent further antigen exposure and hemolysis. Notify blood bank for investigation.<br><br>Take Notes: Continue with antihistamines → only for mild allergic | Antihistamines/steroids → after stopping | Transfusion reaction = stop transfusion first."},
/*32*/ {"q":"A female presents with heavy vaginal bleeding after a difficult home delivery. Most likely cause?","o":["Uterine atony","Bleeding disorder","Retained placental tissue","Genital tract lacerations","Placenta previa"],"a":0,"e":"Uterine atony causes 75-80% of primary postpartum hemorrhage (within 24h); the uterus fails to contract, allowing continued bleeding from placental site. Risk: prolonged labour, multiparity, multiple gestation.<br><br>Take Notes: Retained tissue → 2nd cause | Lacerations → trauma | PPH most common cause = uterine atony."},
/*33*/ {"q":"A patient presents with a thyroid mass. Biopsy reveals psammoma bodies and Orphan Annie eye nuclei. Most likely diagnosis?","o":["Papillary thyroid carcinoma","Follicular thyroid carcinoma","Medullary thyroid carcinoma","Anaplastic thyroid carcinoma","Hurthle cell carcinoma"],"a":0,"e":"Papillary thyroid carcinoma: characteristic ground-glass \"Orphan Annie eye\" nuclei, nuclear grooves, and psammoma bodies (concentric calcifications). Most common thyroid cancer with excellent prognosis.<br><br>Take Notes: Follicular → vascular invasion, no psammoma | Medullary → calcitonin, amyloid | Orphan Annie + psammoma = papillary."},
/*34*/ {"q":"Follicular CA feature is:","o":["Vascular invasion","Psammoma bodies","Lymphatic invasion","Lymphatic spread","Capsular invasion only"],"a":0,"e":"Follicular thyroid carcinoma is distinguished from follicular adenoma by capsular or vascular invasion — hematogenous spread to lung and bone is typical. Lymphatic spread is uncommon (unlike papillary).<br><br>Take Notes: Papillary → lymphatic + psammoma | Medullary → amyloid + calcitonin | Follicular = vascular invasion (hematogenous)."},
/*35*/ {"q":"A 2-year-old child presented with a midline swelling just below the hyoid bone. The swelling was noticed at 3 months of age and is slowly increasing in size, with movements on protrusion of tongue. The condition most likely is:","o":["Accessory thymic tissue","Branchial cyst","Craniopharyngioma","Ectopic thyroid gland","Thyroglossal duct cyst"],"a":4,"e":"Thyroglossal duct cyst: midline neck swelling that moves up on tongue protrusion and swallowing due to attachment to hyoid via thyroglossal duct remnant; most common congenital neck mass in children.<br><br>Take Notes: Branchial cyst → lateral neck | Ectopic thyroid → lingual usually | Midline + moves with tongue = thyroglossal duct cyst."},
/*36*/ {"q":"A female presents with heavy vaginal bleeding. What is the most likely diagnosis?","o":["Uterine fibroids (leiomyoma)","Adenomyosis","Endometriosis","Endometritis","Chronic pelvic inflammatory disease"],"a":0,"e":"Uterine fibroids (leiomyomas) are the most common cause of menorrhagia in reproductive-age women; benign smooth muscle tumours of myometrium. Submucosal fibroids most associated with heavy bleeding.<br><br>Take Notes: Adenomyosis → tender, boggy, diffuse | Endometriosis → cyclical pain | Menorrhagia + bulky uterus = fibroids."},
/*37*/ {"q":"A 19-year-old girl presents with a lack of height increase (4 feet 2 inches) after puberty. She has a normal blood profile and blood sugar levels, with no other issues. Which hormonal abnormality is most likely to be observed?","o":["Increased somatostatin","Decreased IGF-1","Deranged T3 & T4","Increased insulin","Increased cortisol"],"a":1,"e":"Short stature with no other systemic illness suggests growth hormone deficiency; decreased IGF-1 (somatomedin C) is the best screening test as it reflects integrated 24-hour GH secretion.<br><br>Take Notes: T3/T4 abnormality → cretinism (other features) | Insulin/cortisol → other syndromes | Short stature workup = decreased IGF-1."},
/*38*/ {"q":"Elder patient has head injury due to fall. He cannot recall past memory due to damage of:","o":["Parietal lobe","Temporal lobe","Occipital lobe","Frontal lobe","Hippocampus"],"a":1,"e":"Long-term memory storage and recall is located primarily in temporal lobe (with hippocampus); damage causes anterograde and retrograde amnesia. Medial temporal lobe is most critical.<br><br>Take Notes: Parietal → spatial awareness | Frontal → personality/executive | Memory loss after trauma = temporal lobe."},
/*39*/ {"q":"A 48-year-old male presents with complaint of severe throbbing headache and blurring of vision; doctor performed LP and found CSF is blood-stained with RBCs. Possible cause of this blood-stained CSF cause is:","o":["Subdural hemorrhage","Epidural hemorrhage","Subarachnoid hemorrhage","Extradural hemorrhage","Intraparenchymal hemorrhage"],"a":2,"e":"Subarachnoid hemorrhage presents with thunderclap headache and blood-stained CSF on LP; xanthochromia confirms by 12h post-bleed. Berry aneurysm rupture most common (80%) cause.<br><br>Take Notes: Subdural/epidural → space-occupying, not in CSF | Thunderclap headache + bloody CSF = SAH."},
/*40*/ {"q":"Blowout fracture of orbit with proptosis and loss of cheek sensation. It's due to:","o":["Check edema","Zygoma","Infraorbital nerve damage","Infraorbital nerve entrapment at its foramen","Orbital floor fracture"],"a":2,"e":"Orbital blowout fracture (orbital floor) damages the infraorbital nerve (V2 branch) causing cheek numbness; enophthalmos from orbital contents prolapsing into maxillary sinus is more typical than proptosis.<br><br>Take Notes: Zygomatic fracture → flat cheek | Infraorbital nerve = V2 branch | Cheek sensory loss = infraorbital nerve damage."},
/*41*/ {"q":"30-year-old female with fever, headache, ptosis, mydriasis, and isochoric bilateral horizontal diplopia. Nerve involved is:","o":["Abducent nerve palsy","Trochlear nerve","Oculomotor nerve","Trigeminal nerve","Optic nerve"],"a":2,"e":"Oculomotor (CN III) palsy: ptosis (levator palpebrae), mydriasis (loss of parasympathetic constriction), and \"down and out\" eye with diplopia. May indicate compressive lesion (aneurysm) or ischemia.<br><br>Take Notes: Abducens → lateral rectus only (no ptosis/mydriasis) | Trochlear → vertical diplopia | Ptosis + mydriasis + diplopia = CN III."},
/*42*/ {"q":"Nerve supply to the skin below the orbit of the eyes and above the mouth:","o":["Mandibular nerve","Facial nerve","Maxillary nerve","Zygomatic nerve","Ophthalmic nerve"],"a":2,"e":"The mid-facial skin between eye and mouth is supplied by the maxillary nerve (V2) — sensory only; covers cheek, upper lip, lateral nose. Facial nerve provides motor only (not sensation).<br><br>Take Notes: V1 (ophthalmic) → forehead/upper face | V3 (mandibular) → lower face | Mid-face below eye = V2 maxillary."},
/*43*/ {"q":"Location of the geniculate ganglion:","o":["Medial wall of the internal ear","At the junction where the internal acoustic meatus meets the facial canal","At the stylomastoid foramen","Within the parotid gland","In the middle ear"],"a":1,"e":"The geniculate ganglion is the sensory ganglion of the facial nerve, located at the junction where the internal acoustic meatus meets the facial canal at the first bend.<br><br>Take Notes: Stylomastoid foramen → facial nerve exit | Parotid → branching point | Geniculate ganglion = IAM meets facial canal."},
/*44*/ {"q":"A patient with a recent history of mumps and viral exposure presents with headache, fever, and neck stiffness. Laboratory tests show raised lymphocytes in cerebrospinal fluid (CSF). Most likely diagnosis?","o":["Viral meningitis","Bacterial meningitis","Tuberculous meningitis","Fungal meningitis","Encephalitis"],"a":0,"e":"Mumps and other viruses cause aseptic meningitis with lymphocytic pleocytosis in CSF, normal/slightly elevated protein, normal glucose. Bacterial would show neutrophils with very high protein and low glucose.<br><br>Take Notes: Bacterial → neutrophils, low glucose | TB → lymphocytes, very low glucose | Viral mumps + lymphocytes = viral meningitis."},
/*45*/ {"q":"From which structure does the facial nerve primarily arise?","o":["Pons","Cerebellopontine angle","Medulla oblongata","Midbrain","Cervical cord"],"a":0,"e":"The facial nerve (CN VII) emerges from the lower border of the pons at the cerebellopontine angle; the seventh cranial nerve nucleus lies in the pontine tegmentum.<br><br>Take Notes: Cerebellopontine angle = location, not origin | Midbrain → CN III, IV | Medulla → CN IX, X, XI, XII | CN VII = pons."},
/*46*/ {"q":"A 50-year-old patient presents with diplopia, ptosis, weakness in chewing after prolonged effort, normal pupils, dryness of mouth, proximal muscle weakness, and loss of deep tendon reflexes. Most likely diagnosis?","o":["Myasthenia gravis","Lambert-Eaton syndrome","Multiple sclerosis","Botulism","Guillain-Barre syndrome"],"a":1,"e":"Lambert-Eaton myasthenic syndrome: presynaptic Ca channel antibodies cause autonomic dysfunction (dry mouth), proximal weakness, areflexia, and IMPROVEMENT with exercise. Associated with small cell lung cancer.<br><br>Take Notes: Myasthenia → worsens with use + normal reflexes | Lambert-Eaton = improves with use + areflexia + autonomic."},
/*47*/ {"q":"A 35-year-old patient presents with morning stiffness lasting more than one hour, accompanied by pain and swelling in metacarpophalangeal (MCP) and proximal interphalangeal (PIP) joints of both hands. What is the most likely diagnosis?","o":["Rheumatoid arthritis","Osteoarthritis","Gout","Systemic lupus erythematosus","Psoriatic arthritis"],"a":0,"e":"Rheumatoid arthritis: symmetric polyarthritis of MCP and PIP joints with morning stiffness >1 hour. Spares DIP joints (unlike OA, psoriatic). Females predominate; anti-CCP and RF positive.<br><br>Take Notes: OA → asymmetric, DIP involved | Gout → monoarticular, painful flare | Morning stiffness + MCP/PIP = RA."},
/*48*/ {"q":"A 28-year-old male presents with morning stiffness and reduced movement in the lower back. His symptoms improve with activity but worsen after rest. On examination, lumbar spine flexion is limited. There is history of diarrhea alternating with constipation as well. Most likely diagnosis?","o":["Ankylosing spondylitis","Lumbar disc herniation","Osteoarthritis of the spine","Muscle strain","Rheumatoid arthritis"],"a":0,"e":"Ankylosing spondylitis: chronic inflammatory back pain (>3 months) with morning stiffness improving with exercise; young males; HLA-B27 association. IBD coexistence in 5-10%. Sacroiliitis is hallmark.<br><br>Take Notes: Disc herniation → worse with activity | OA → no morning stiffness | Young male + back pain + IBD = AS."},
/*49*/ {"q":"A female had aortic root dilation upto 4cm, ocular examination showed lens dislocation, mitral valve leaflet defect with systolic click. Defect in which of the following?","o":["Acquired deficiency of fibrillin","Inherited deficiency of fibrillin","Inherited deficiency of laminin","Acquired deficiency of spectrin","Inherited deficiency of dystrophin"],"a":1,"e":"Marfan syndrome: autosomal dominant FBN1 mutation causes inherited fibrillin-1 defect; manifests as aortic root dilation (dissection risk), ectopia lentis (upward), and MVP. Risk of aortic dissection.<br><br>Take Notes: Spectrin → spherocytosis | Dystrophin → Duchenne | Inherited fibrillin defect = Marfan syndrome."},
/*50*/ {"q":"Click defect in which of the following?","o":["Acquired deficiency of fibrillin","Inherited deficiency of fibrillin","Acquired deficiency of laminin","Acquired deficiency of Spectrin","Inherited deficiency of dystrophin"],"a":1,"e":"Mitral valve prolapse with systolic click in young patient suggests connective tissue defect — inherited fibrillin deficiency (Marfan syndrome). Floppy mitral leaflets from myxoid degeneration produce mid-systolic click.<br><br>Take Notes: Acquired deficiencies → secondary | Marfan + MVP click = inherited fibrillin defect (FBN1)."},
/*51*/ {"q":"A woman after one hour undergoes a PPD test for TB; induration of about 3mm in arm. The phenomena is due to:","o":["Type 4 hypersensitivity","Type 3 hypersensitivity","Type 1 hypersensitivity","Type 2 hypersensitivity","Anaphylaxis"],"a":0,"e":"PPD (Mantoux/tuberculin) test demonstrates type IV (delayed) hypersensitivity: T cell-mediated response to mycobacterial antigens. Induration develops over 48-72 hours, not within one hour.<br><br>Take Notes: Type I → IgE (immediate) | Type III → immune complex | TB skin test = type IV (delayed)."},
/*52*/ {"q":"A patient suffers from appendicitis. Peripheral blood shows leukocytosis. He is having fever and pain. Pain will be mediated by:","o":["IL-1 and TNF-α","Serotonin","IL-6","Bradykinin","Prostaglandins"],"a":3,"e":"In acute inflammation, bradykinin is the principal mediator of pain — produced by kallikrein-kinin system activation; sensitises nociceptors and causes vasodilation. Prostaglandins potentiate bradykinin action.<br><br>Take Notes: IL-1/TNF/IL-6 → fever (pyrogens) | Serotonin → mood, gut | Inflammatory pain = bradykinin."},
/*53*/ {"q":"A patient with HIV develops pneumonia caused by Pneumocystis jirovecii. At what CD4+ T-cell count does this infection most commonly occur?","o":["CD4 count < 200 cells/mm³","CD4 count < 500 cells/mm³","CD4 count < 1000 cells/mm³","CD4 count > 500 cells/mm³","CD4 count < 50 cells/mm³"],"a":0,"e":"Pneumocystis jirovecii pneumonia (PJP) occurs when CD4 count falls below 200 cells/mm³ in HIV patients. Prophylaxis with TMP-SMX (Bactrim) is indicated at this threshold to prevent infection.<br><br>Take Notes: Cryptococcus → <100 | MAC → <50 | Below 200 = PJP prophylaxis indicated."},
/*54*/ {"q":"Click defect in which of the following?","o":["Acquired deficiency of fibrillin","Inherited deficiency of fibrillin","Inherited deficiency of laminin","Acquired deficiency of spectrin","Acquired deficiency of dystrophin"],"a":1,"e":"Marfan syndrome involves inherited fibrillin-1 deficiency (FBN1 gene, autosomal dominant); manifests as aortic root dilation, lens dislocation, and mitral valve prolapse with mid-systolic click.<br><br>Take Notes: Spectrin → spherocytosis | Dystrophin → Duchenne | MVP click in Marfan = inherited fibrillin deficiency."},
/*55*/ {"q":"A cell was on microscopic examination large mitochondrial densities are found indicating:","o":["Irreversible cell injury","Apoptosis","Necrosis","Reversible cell injury","Autophagy"],"a":0,"e":"Mitochondrial densities (calcium-rich amorphous deposits) on electron microscopy are markers of irreversible cell injury (necrosis); reversible injury shows mitochondrial swelling without densities.<br><br>Take Notes: Mitochondrial swelling → reversible | Mitochondrial densities → irreversible | Cell death point = mitochondrial densities."},
/*56*/ {"q":"A patient presents with ptosis, B (Robins) anhidrosis on one side of the face, and which of the following clinical features is also part of Horner syndrome?","o":["Miosis","Mydriasis","Exophthalmos","Diplopia","Hyperhidrosis"],"a":0,"e":"Horner syndrome triad: ptosis (partial), miosis (sympathetic constrictor loss), and anhidrosis (loss of sweating) on affected side. Caused by sympathetic chain disruption (Pancoast tumour, carotid dissection).<br><br>Take Notes: Mydriasis → CN III lesion (opposite) | Exophthalmos → Graves | Horner = ptosis + miosis + anhidrosis."},
/*57*/ {"q":"What is codominance?","o":["A dominant gene will overpower all other genes to be the only one expressed","One is recessive and other gene is dominant","Where two different traits are both expressed alongside each other","None","Two recessive genes are co-expressed"],"a":2,"e":"Codominance: both alleles are fully expressed simultaneously in the heterozygote, neither dominant nor recessive. Classic example: ABO blood group AB phenotype (both A and B antigens expressed).<br><br>Take Notes: Complete dominance → one allele masks other | Incomplete dominance → blended | Codominance = both alleles expressed."},
/*58*/ {"q":"A female patient presents with an adnexal mass suspicious for ovarian carcinoma. Which tumor marker is most commonly elevated in this condition?","o":["CA 125","AFP","CEA","Beta-hCG","LDH"],"a":0,"e":"CA 125 is the primary tumor marker for epithelial ovarian carcinoma — raised in >80% of serous ovarian cancers. Used for diagnosis, monitoring treatment, and detecting recurrence (post-resection).<br><br>Take Notes: AFP → yolk sac/HCC | Beta-hCG → choriocarcinoma | CEA → colon | Ovarian carcinoma = CA 125."},
/*59*/ {"q":"A girl presented to her physician with concern, both her mother and sister died of metastatic breast cancer before 40 years of age. She is worried about herself. Which of the following gene is mutated?","o":["Multiparity","APC","RAS","BRCA1 mutation","Fibroadenoma"],"a":3,"e":"BRCA1 mutation confers 55-65% lifetime breast cancer risk and early presentation (<40 years); strong family history of premenopausal breast cancer in first-degree relatives suggests hereditary BRCA1.<br><br>Take Notes: APC → FAP, colon CA | RAS → various cancers | BRCA1 → breast + ovarian CA familial."},
/*60*/ {"q":"Complement activation is primarily triggered by which of the following immunoglobulins?","o":["IgM and IgG","IgD and IgE","IgA","IgG only","IgE only"],"a":0,"e":"Classical complement pathway activation requires IgM (single molecule sufficient) or IgG (multiple molecules); IgM is the most efficient activator due to its pentameric structure with five Fc regions.<br><br>Take Notes: IgA → mucosal | IgE → allergy | IgD → B cell receptor | Complement classical = IgM > IgG."},
/*61*/ {"q":"The waterproofing effect of the skin is primarily due to which of the following?","o":["Keratin","Melanin","Collagen","Elastin","Sebum"],"a":0,"e":"Keratin is the waterproofing protein of the skin: a tough, insoluble fibrous protein in the stratum corneum that prevents water loss and protects against external damage. Maintains hydration barrier.<br><br>Take Notes: Melanin → UV protection | Collagen → tensile strength | Skin waterproofing = keratin."},
/*62*/ {"q":"Kaposi sarcoma is caused by:","o":["HHV-8","HHV-6","HHV-7","B-19","HHV-5"],"a":0,"e":"Kaposi sarcoma is caused by Human Herpesvirus 8 (HHV-8); commonly seen in AIDS patients (advanced HIV), Mediterranean elderly, and post-transplant patients. Causes vascular cutaneous neoplasms.<br><br>Take Notes: HHV-6/7 → roseola infantum | B19 → erythema infectiosum (fifth disease) | Kaposi sarcoma = HHV-8."},
/*63*/ {"q":"Postmortem clot differentiated from clot supernatant. Chicken fat appearance is seen in:","o":["Chicken fat supernatant","Pre-mortem thrombus","Mural thrombus","Chicken lipid thrombus","Postmortem thrombus"],"a":4,"e":"Postmortem clots have a characteristic \"chicken fat\" appearance (yellow upper layer from settled plasma) over \"red currant jelly\" (lower red layer with RBCs); smooth shiny surface and unattached to vessel wall.<br><br>Take Notes: Antemortem clot → dry, friable, attached | Lines of Zahn → antemortem | Chicken fat = postmortem."},
/*64*/ {"q":"What type of necrosis is seen in brain?","o":["Fat necrosis","Coagulative necrosis","Fibrinoid necrosis","Liquefactive necrosis","Medial necrosis"],"a":3,"e":"Brain undergoes liquefactive necrosis after ischemic injury due to high lipid content and absence of robust supporting stroma; microglial enzymes digest tissue rapidly, leaving cystic cavities.<br><br>Take Notes: Coagulative → heart, kidney, spleen | Caseous → TB | Liquefactive = brain + bacterial abscess."},
/*65*/ {"q":"Pleural fluid with inflammatory cells, eosinophils, mesh of threads of amorphous coagulum. Type of inflammation is:","o":["Fibrinous inflammation","Serous inflammation","Chronic","Acute","Granulomatous"],"a":0,"e":"Fibrinous inflammation: protein-rich exudate with fibrin meshwork on serosal surfaces (pleura, pericardium). Common in TB, uremia, rheumatic fever. May organise into adhesions if not resolved.<br><br>Take Notes: Serous → clear fluid (early) | Suppurative → pus | Fibrin meshwork + threads = fibrinous inflammation."},
/*66*/ {"q":"Cheilosis and corneal vascularization is due to deficiency of which of the following vitamin?","o":["Thiamine","Biotin","Riboflavin","Folate","Vitamin C"],"a":2,"e":"Vitamin B2 (riboflavin) deficiency: cheilosis (angular cracking of mouth), glossitis, seborrheic dermatitis, and corneal vascularization. B2 is essential for FMN and FAD coenzymes.<br><br>Take Notes: Thiamine (B1) → beriberi, Wernicke | Biotin → dermatitis | Cheilosis + corneal vascularization = riboflavin."},
/*67*/ {"q":"A child presents with keratomalacia, dryness, and blurred vision. Which vitamin deficiency is most likely responsible?","o":["Vitamin C","Vitamin B12","Vitamin A","Vitamin K","Vitamin D"],"a":2,"e":"Vitamin A deficiency: night blindness (early), Bitot spots, xerophthalmia, keratomalacia (corneal softening) leading to blindness. Common in developing countries; reversible with prompt treatment.<br><br>Take Notes: B12 → megaloblastic + neuro | C → scurvy | D → rickets | Keratomalacia + night blindness = vitamin A."},
/*68*/ {"q":"Which of the following has anti-oxidant properties?","o":["Vitamin B12","Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"a":2,"e":"Vitamin C (ascorbic acid) is a major water-soluble antioxidant; scavenges free radicals and regenerates vitamin E. Also acts as cofactor for collagen hydroxylation (prevents scurvy).<br><br>Take Notes: Vitamin E → lipid-soluble antioxidant | Glutathione → intracellular | Water-soluble antioxidant = vitamin C."},
/*69*/ {"q":"An elderly woman on multiple medications presents with irritability and serum sodium of 115 mmol/L (hyponatremia). Which drug is most likely responsible for causing hyponatremia?","o":["Escitalopram","Metformin","Amlodipine","Atorvastatin","Furosemide"],"a":0,"e":"SSRIs (escitalopram, sertraline) commonly cause hyponatremia via SIADH (syndrome of inappropriate ADH), especially in elderly patients. Triggered by ADH release leading to water retention.<br><br>Take Notes: Diuretics → hypokalemia common | Metformin → no Na effect | SSRI in elderly = SIADH hyponatremia."},
/*70*/ {"q":"Tetracycline's activity against Helicobacter pylori results from inhibition of which target?","o":["DNA gyrase","Dihydrofolate reductase","30S ribosomal subunit","Cell-wall transpeptidase","Bacterial RNA polymerase"],"a":2,"e":"Tetracyclines bind reversibly to 30S ribosomal subunit, blocking attachment of aminoacyl-tRNA and preventing protein synthesis. Used in H. pylori quadruple therapy and various other infections.<br><br>Take Notes: DNA gyrase → fluoroquinolones | Cell wall → β-lactams | Tetracyclines = 30S ribosomal subunit."},
/*71*/ {"q":"Which of the following DMARDs is considered safe to use during pregnancy?","o":["Methotrexate","Leflunomide","Sulfasalazine","Hydroxychloroquine","All of the above"],"a":3,"e":"Hydroxychloroquine is the safest DMARD in pregnancy (category C — no proven teratogenicity); used for RA and SLE in pregnancy. Methotrexate and leflunomide are absolutely contraindicated (teratogenic).<br><br>Take Notes: Methotrexate → category X (avoid) | Leflunomide → category X | Pregnancy-safe DMARD = hydroxychloroquine."},
/*72*/ {"q":"A 25-year-old male is brought to the ED after ingesting 40 tablets of aspirin in a suicide attempt. He is drowsy, hyperventilating, and has tinnitus. What is the most appropriate next step to enhance urinary excretion of aspirin?","o":["Administer large volume of IV water","Give strong acid orally","Administer IV sodium bicarbonate","Give weak acid","Administer weak base orally"],"a":2,"e":"Aspirin (salicylate) is a weak acid; urinary alkalinization with IV sodium bicarbonate traps salicylate in ionised form in the urine, enhancing renal excretion. Target urinary pH >7.5.<br><br>Take Notes: Acidification → for weak base poisoning | Forced diuresis ineffective | Salicylate poisoning = NaHCO3 alkalinization."},
/*73*/ {"q":"A patient presents with weakness of thenar muscles and loss of sensation over thumb and index finger. Which nerve is most likely affected?","o":["Median nerve","Ulnar nerve","Radial nerve","Musculocutaneous nerve","Anterior interosseous nerve"],"a":0,"e":"Median nerve supplies thenar muscles (LOAF) and sensation to lateral palm including thumb and index finger; carpal tunnel syndrome causes thenar wasting and lateral digit numbness.<br><br>Take Notes: Ulnar → hypothenar + medial 1.5 fingers | Radial → wrist drop + dorsum | Thenar + thumb/index = median nerve."},
/*74*/ {"q":"A patient is having difficulty from sitting to standing position. Which muscle will be likely injured?","o":["Gluteal muscles","Hamstring","Popliteus","Obturator internus","Quadriceps"],"a":0,"e":"Rising from sitting to standing requires hip extension by gluteus maximus (primary) and hamstrings; gluteus maximus weakness causes difficulty in this movement, climbing stairs, and rising from chair.<br><br>Take Notes: Hamstrings → also assist | Popliteus → unlocks knee | Sit-to-stand difficulty = gluteus maximus."},
/*75*/ {"q":"Ligament damaged in 3rd degree prolapse:","o":["Uterine ligament","Broad ligament","Round ligament","Inguinal ligament","Uterosacral ligament"],"a":4,"e":"Uterosacral ligaments are the chief posterior support of cervix and upper vagina; their damage causes uterovaginal prolapse. In 3rd degree (cervix outside introitus), uterosacral > cardinal involvement.<br><br>Take Notes: 1st-2nd degree → uterosacral mainly | 4th degree → cardinal ligament | 3rd degree = uterosacral."},
/*76*/ {"q":"A patient is lying supine on the operating table and undergoes laparotomy. If 1 litre of normal saline is accidentally spilled into the open abdomen, where will the fluid most likely accumulate?","o":["Right and left paracolic gutters","Right and left subphrenic spaces","Right and left subhepatic spaces","Uterine pouch","Pelvic cavity"],"a":0,"e":"In supine position, the paracolic gutters (lateral to ascending and descending colon) are the most dependent areas of the abdomen and fluid pools here. Also drains pelvic structures.<br><br>Take Notes: Subphrenic → upright position | Pouch of Douglas → upright | Supine + spilled fluid = paracolic gutters."},
/*77*/ {"q":"Female patient presents with increased frequency and urgency, diagnosed as UTI. Microscopy shows gram-negative motile rods, urease-positive, lactose non-fermenting on MacConkey agar. Likely organism?","o":["Pseudomonas","Campylobacter","Proteus mirabilis","Klebsiella","E. coli"],"a":2,"e":"Proteus mirabilis: gram-negative motile rods (swarming), urease positive (alkalinises urine → struvite stones), lactose non-fermenter on MacConkey agar. Second most common UTI cause after E. coli.<br><br>Take Notes: E. coli → lactose fermenter | Klebsiella → non-motile | Urease+ + swarming = Proteus."},
/*78*/ {"q":"The embryological layer from which the rectum is derived is:","o":["Endoderm","Mesoderm","Ectoderm","Neural crest cells","All germ layers"],"a":0,"e":"The rectum (along with most GI tract epithelium) is derived from endoderm. The hindgut endoderm forms the distal 2/3 of transverse colon, descending colon, sigmoid, and upper rectum.<br><br>Take Notes: Mesoderm → smooth muscle of gut | Ectoderm → epidermis, neural tube | GI tract epithelium = endoderm."},
/*79*/ {"q":"A baby's intestine does not get back. Abdominal contents are covered with amniotic layer. Most possible diagnosis is:","o":["Gastroschisis","Omphalocele","Meckel's diverticulum","Intussusception","Volvulus"],"a":1,"e":"Omphalocele: midline abdominal wall defect at umbilicus where intestines herniate covered by peritoneum, Wharton's jelly, and amniotic membrane. Associated with chromosomal anomalies (trisomy 13, 18, 21).<br><br>Take Notes: Gastroschisis → no covering, right of umbilicus | Meckel → ileal diverticulum | Covered defect = omphalocele."},
/*80*/ {"q":"Myelination during intrauterine life begins at:","o":["Just before birth","At 6 months gestation","Before 3 months gestation","After birth","2nd trimester"],"a":1,"e":"CNS myelination begins at 6 months gestation and continues into adulthood (especially postnatally); peripheral nerve myelination starts earlier. Myelination disorders affect early brain development.<br><br>Take Notes: PNS myelination → starts in 2nd trimester | CNS myelination = peaks postnatally | Begins at 6 months gestation."},
/*81*/ {"q":"A diabetic female patient has swelling over the lateral malleolus. Before the imaging scan, she is given FDG (fluorodeoxyglucose) for evaluation. Which modality is being used?","o":["PET scan","CT scan","MRI scan","Ultrasound scan","Bone scan"],"a":0,"e":"FDG (fluorodeoxyglucose, F-18 labelled) is the standard radiotracer for PET imaging; metabolically active tissues (inflammation, infection, malignancy) take up FDG, emitting positrons for detection.<br><br>Take Notes: Tc-99m → bone scans | Iodine → thyroid | CT/MRI → no radiotracer | FDG = PET scan."},
/*82*/ {"q":"A patient died of fat embolism on autopsy. Fat embolism will be visualized by:","o":["Trichome stain","Permanent Silver stain","Frozen fat sections with fat stain","Permanent fat content","Frozen fat sections with silica stain"],"a":2,"e":"Fat embolism diagnosis requires frozen sections (formalin processing dissolves fat) stained with fat stains (Oil Red O, Sudan III/IV) to demonstrate intravascular fat globules.<br><br>Take Notes: Routine paraffin processing → dissolves fat | Trichrome → connective tissue | Fat embolism = frozen sections + fat stain."},
/*83*/ {"q":"A female patient presents in Gynae OPD with third degree UV prolapse, which occurs due to damage of uterosacral ligament. Which of the following structures attaches the uterosacral ligament to the cervix?","o":["Anterior pelvic wall","Rectum","Urinary bladder","Round ligament","Posterior pelvic wall (sacrum)"],"a":4,"e":"Uterosacral ligaments are the major posterior support of cervix and upper vagina; extend from posterolateral cervix to sacrum (S2-S4). Damage leads to uterovaginal prolapse.<br><br>Take Notes: Round ligament → cervix to labia | Pubocervical → cervix to pubis | Uterosacral = cervix to sacrum."},
/*84*/ {"q":"Chloramphenicol causes grey baby syndrome by which of the following pathways?","o":["Glucuronidation","Sulfation","Acetylation","Oxidation","Hydroxylation"],"a":0,"e":"Chloramphenicol causes grey baby syndrome in neonates due to immature hepatic glucuronidation (UDP-glucuronosyltransferase deficiency); drug accumulates causing cyanosis, cardiovascular collapse, and high mortality.<br><br>Take Notes: Glucuronidation → primary chloramphenicol metabolism | Neonatal immaturity → drug accumulation | Grey baby = failed glucuronidation."},
/*85*/ {"q":"Which of the following DPP-4 inhibitors is primarily excreted in feces and does not require dose adjustment in patients with renal impairment?","o":["Linagliptin","Sitagliptin","Vildagliptin","Saxagliptin","Alogliptin"],"a":0,"e":"Linagliptin is the only DPP-4 inhibitor with primarily biliary/fecal excretion (>80%), requiring no dose adjustment in renal impairment. Other DPP-4 inhibitors are renally cleared.<br><br>Take Notes: Sitagliptin/saxagliptin → renal clearance | Vildagliptin → also renal | Renal-friendly DPP-4 = linagliptin."},
/*86*/ {"q":"A diagnosed UTI patient on microscopy shows gram-negative non-motile rods. Urease positive, lactose non-fermenting on MacConkey agar. Most likely organism involved is:","o":["Pseudomonas","Campylobacter","Proteus mirabilis","Klebsiella","E. coli"],"a":2,"e":"Proteus mirabilis: gram-negative motile rods, urease positive (alkalinises urine causing struvite stones), lactose non-fermenter (NLF on MacConkey). Common cause of UTI especially with stones.<br><br>Take Notes: Klebsiella → non-motile but lactose+ | E. coli → lactose fermenter | Urease+ NLF = Proteus."},
/*87*/ {"q":"A pregnant woman complains of metallic taste in her mouth. Which channel is inhibited?","o":["Sweet","Sour","Bitter","Salty","Umami"],"a":1,"e":"Sour taste sensation is generated by potassium channels; inhibition leads to depolarization and action potential generation. Metallic taste in pregnancy involves dysgeusia from hormonal changes.<br><br>Take Notes: Sweet → sugars via T1R receptors | Bitter → T2R | Salty → ENaC sodium | Sour = K+ channel."},
/*88*/ {"q":"If the radial nerve is damaged, which area will experience sensory loss?","o":["Narrow strip over the posterior arm and forearm","Medial aspect of the forearm and thumb","Lateral palm and thumb","Plantar surface of the foot","Dorsum of hand including thumb base"],"a":0,"e":"Radial nerve provides sensory innervation to a narrow strip over the posterior arm and forearm, plus dorsum of lateral hand. The autonomous zone is dorsal first web space (radial sensation).<br><br>Take Notes: Median → lateral palm + lateral 3.5 fingers | Ulnar → medial 1.5 + medial palm | Radial = posterior arm/forearm strip."},
/*89*/ {"q":"One-year-old child presented with diarrhoea after 1 year. History of some milk intake is given by mother. Doctor asked her to stop giving milk to baby. Cause is:","o":["Sprue disease","Lactose intolerance","Hirschsprung disease","Celiac disease","Cystic fibrosis"],"a":1,"e":"Lactose intolerance: lactase enzyme deficiency causes diarrhea, bloating, and abdominal pain after milk ingestion. Lactose is fermented by colonic bacteria producing gas and osmotic diarrhea.<br><br>Take Notes: Sprue → gluten sensitivity | Hirschsprung → constipation | Celiac → gluten | Milk diarrhea = lactose intolerance."},
/*90*/ {"q":"After gastric bypass surgery, why does the patient often develop increased fat in the stool?","o":["Reduced absorptive area of the intestine","Food bypasses the stomach when entered the intestine too quickly","Increased pancreatic enzyme secretion","Increased bile acid production","Decreased gastric acid"],"a":0,"e":"Gastric bypass (Roux-en-Y) bypasses duodenum and proximal jejunum, reducing absorptive surface area and pancreatic enzyme mixing with chyme; causes malabsorption and steatorrhea with fat-soluble vitamin deficiencies.<br><br>Take Notes: Bypassed duodenum → reduced enzymes mixing | Steatorrhea common | Gastric bypass = reduced absorptive surface."},
/*91*/ {"q":"If the tibial part of the sciatic nerve is damaged, which nerve supplies the short head of biceps femoris that still performs dorsiflexion?","o":["Common peroneal nerve","Tibial nerve","Femoral nerve","Obturator nerve","Sciatic main trunk"],"a":0,"e":"Biceps femoris has dual innervation: long head by tibial division of sciatic; short head by common peroneal division. With tibial injury, common peroneal-supplied short head and dorsiflexors remain.<br><br>Take Notes: Tibial → plantarflexion + sole | Common peroneal → dorsiflexion + lateral leg | Short head BF = common peroneal."},
/*92*/ {"q":"Which of the following statements about metformin is correct?","o":["Causes weight gain","Is not the first-line drug for starting diabetes treatment","Decreases hepatic gluconeogenesis","Increases insulin secretion","Causes hypoglycemia"],"a":2,"e":"Metformin's primary mechanism is reduction of hepatic gluconeogenesis through AMPK activation; doesn't stimulate insulin secretion (so no hypoglycemia), weight-neutral, and is first-line for type 2 diabetes.<br><br>Take Notes: Sulfonylureas → cause weight gain + hypoglycemia | First-line T2DM = metformin | Mechanism = decreased hepatic gluconeogenesis."},
/*93*/ {"q":"A young patient presents with recurrent chest infections and chronic diarrhea. Most likely finding on imaging?","o":["Normal lung fields","Pulmonary fibrosis","Pleural effusion","Reticulonodular infiltrates","Bronchiectasis"],"a":4,"e":"Cystic fibrosis: recurrent respiratory infections from thick airway secretions cause bronchiectasis (dilated, damaged airways) on imaging; pancreatic insufficiency causes chronic diarrhea/steatorrhea. CFTR gene mutation.<br><br>Take Notes: Pulmonary fibrosis → interstitial | Effusion → pleural | Recurrent infections + diarrhea = CF = bronchiectasis."},
/*94*/ {"q":"An obese woman has normal T3 and T4 but elevated TSH and is infertile. What is the most likely diagnosis?","o":["Primary hypothyroidism","Secondary hypothyroidism","Pituitary adenoma","Diabetes mellitus","Subclinical hypothyroidism"],"a":4,"e":"Subclinical hypothyroidism: elevated TSH with normal T3/T4 levels. May cause infertility, weight changes, and progress to overt hypothyroidism. Treatment indicated if TSH >10 or infertility/symptoms.<br><br>Take Notes: Primary hypothyroidism → low T4 + high TSH | Secondary → low TSH | Normal T3/T4 + raised TSH = subclinical."},
/*95*/ {"q":"A patient presents with midline neck swelling and lumbar pains. Investigations reveal low serum calcium and elevated calcitonin levels. Most likely diagnosis?","o":["MEN 1","MEN 2","Familial medullary thyroid carcinoma","Sporadic medullary thyroid carcinoma","Papillary thyroid carcinoma"],"a":1,"e":"MEN 2 syndromes (RET mutation) include medullary thyroid carcinoma (elevated calcitonin) with parathyroid involvement (low calcium possible) and pheochromocytoma. Hereditary pattern suggests MEN 2.<br><br>Take Notes: MEN 1 → pituitary + pancreas + parathyroid (3Ps) | Sporadic MTC → single | Familial MTC + parathyroid = MEN 2."},
/*96*/ {"q":"An obese woman with a BMI of 35 has a fasting insulin of 25 μIU/mL (normal ≤20), fasting blood sugar of 110 mg/dL (normal ≤100), and elevated triglycerides and LDL levels. What is the most likely cause of her obesity?","o":["Insulin resistance causing compensatory hyperinsulinemia","Excessive caloric intake","Hypothyroidism","Cushing syndrome","Genetic mutation"],"a":0,"e":"Metabolic syndrome: insulin resistance is the central pathology; compensatory hyperinsulinemia, dyslipidemia (high TG, low HDL), hypertension, and central obesity. Insulin resistance precedes diabetes.<br><br>Take Notes: Cushing → striae + buffalo hump | Hypothyroidism → low metabolic rate | Elevated insulin + dyslipidemia = insulin resistance."},
/*97*/ {"q":"What is the mechanism of action of pioglitazone?","o":["Binds to peroxisome proliferator-activated receptor gamma (PPARγ)","Stimulates pancreatic insulin secretion","Inhibits alpha-glucosidase in the intestine","Increases renal glucose excretion","Inhibits hepatic gluconeogenesis"],"a":0,"e":"Pioglitazone (thiazolidinedione) activates PPAR-γ nuclear receptors, enhancing insulin sensitivity in adipose tissue, muscle, and liver. Increases adiponectin and improves lipid profile.<br><br>Take Notes: Sulfonylureas → stimulate insulin secretion | Acarbose → alpha-glucosidase | SGLT2 → renal | Pioglitazone = PPAR-γ."},
/*98*/ {"q":"During which period of pregnancy does rubella infection most commonly cause congenital heart defects?","o":["First 5 months","First 3 months","Between 5 to 10 months","Between 5 to 10 weeks","Third trimester"],"a":3,"e":"Congenital rubella syndrome is most teratogenic during 5-10 weeks of gestation when cardiac and organ formation occurs; causes PDA, cataracts, deafness, and microcephaly. First trimester exposure highest risk.<br><br>Take Notes: After 12 weeks → minimal CRS risk | Cataracts → <7 weeks | CRS cardiac defects = 5-10 weeks."},
/*99*/ {"q":"A patient's biopsy shows infiltration of macrophages and lymphocytes. What type of inflammation does this suggest?","o":["Chronic inflammation","Granulomatous inflammation","Acute inflammation","Fibrinous inflammation","Suppurative inflammation"],"a":0,"e":"Macrophages and lymphocytes as the predominant infiltrate indicate chronic inflammation; ongoing tissue injury, attempted repair, and immune response. Lasts weeks to years; develops after acute or directly.<br><br>Take Notes: Acute → neutrophils dominant | Granulomatous → epithelioid giant cells | Macrophages + lymphocytes = chronic."},
/*100*/ {"q":"Gracilis muscle is innervated by which of the following?","o":["Obturator nerve","Sciatic nerve","Pudendal nerve","Femoral nerve","Tibial nerve"],"a":0,"e":"Gracilis muscle (medial thigh) is innervated by anterior division of obturator nerve (L2-L4). It crosses both hip and knee joints, adducting hip and flexing knee. Used as flap in reconstruction.<br><br>Take Notes: Femoral → quadriceps + sartorius | Sciatic → hamstrings | Gracilis = obturator (anterior division)."},
/*101*/ {"q":"A 30-year-old male suddenly died after a sudden rise in blood pressure. At autopsy the ruptured vessel completely lacks the tunica media at the point of aneurysm. Most likely aneurysm is:","o":["Berry aneurysm","Dissecting aneurysm","Marfan aneurysm","Mycotic aneurysm","Atherosclerotic aneurysm"],"a":0,"e":"Berry (saccular) aneurysm: congenital defect with absent tunica media at arterial bifurcations in Circle of Willis; rupture causes spontaneous SAH. Associated with hypertension, polycystic kidney disease.<br><br>Take Notes: Dissecting → intimal tear (Marfan-related) | Mycotic → infectious | Absent media at bifurcation = berry aneurysm."},
/*102*/ {"q":"Superficial ulnar nerve supplies which of the following muscles?","o":["Abductor pollicis brevis","Flexor carpi ulnaris","Opponens pollicis","Palmaris longus","Adductor pollicis"],"a":1,"e":"Ulnar nerve (via deep branches and superficial branches) supplies flexor carpi ulnaris in the forearm and most intrinsic hand muscles. Thenar muscles (LOAF) are median nerve territory.<br><br>Take Notes: APB/opponens pollicis → median nerve (LOAF) | Palmaris longus → median | Ulnar = flexor carpi ulnaris."},
/*103*/ {"q":"Which statement about saliva is correct?","o":["Saliva contains proteases that initiate protein digestion","Salivary secretion is primarily increased by sympathetic activation","Saliva contains amylase that begins carbohydrate digestion","Parasympathetic activation decreases saliva production","Saliva is only secreted from sublingual glands"],"a":2,"e":"Saliva contains alpha-amylase (ptyalin) which initiates carbohydrate digestion in the mouth; cleaves alpha-1,4 glycosidic bonds of starch. Parasympathetic stimulation increases saliva (sympathetic produces thick saliva).<br><br>Take Notes: Parasympathetic → increases watery saliva | Sympathetic → thick mucous saliva | Saliva = amylase (carbohydrates)."},
/*104*/ {"q":"A patient presents with diffuse loss of vibration sense. Which investigation is most appropriate to evaluate the underlying cause?","o":["X-ray of the spine","Urine analysis","Serum vitamin B12 level","Nerve conduction studies","MRI brain"],"a":2,"e":"Diffuse loss of vibration sense suggests subacute combined degeneration of dorsal columns from vitamin B12 deficiency. Serum B12 measurement is the most appropriate initial investigation.<br><br>Take Notes: Folate → no neuro signs | MS → focal not diffuse | Diffuse vibration loss + position sense = B12 deficiency."},
/*105*/ {"q":"Which of the following best describes the mechanism of action of sitagliptin?","o":["Directly stimulates pancreatic beta cells","Inhibits dipeptidyl peptidase-4 (DPP-4), increasing incretin levels","Activates AMP-activated protein kinase to reduce gluconeogenesis","Enhances peripheral insulin receptor sensitivity","Increases insulin sensitivity in muscle"],"a":1,"e":"Sitagliptin inhibits DPP-4 enzyme that normally degrades incretins (GLP-1, GIP); resulting in higher incretin levels which enhance glucose-dependent insulin secretion. No hypoglycemia risk.<br><br>Take Notes: Metformin → AMPK | Pioglitazone → PPAR-γ | Sitagliptin = DPP-4 inhibitor (incretin enhancer)."},
/*106*/ {"q":"Which of the following is the main pillar of medial longitudinal arch of the foot?","o":["Talus","Calcaneum","Cuboid","Cuneiform","Navicular"],"a":0,"e":"The talus is the keystone (apex/pillar) of the medial longitudinal arch of the foot; transmits body weight from tibia to calcaneus and navicular. Maintains arch stability during weight-bearing.<br><br>Take Notes: Calcaneum → posterior pillar | Navicular + cuneiforms + 1st-3rd metatarsals = arch | Apex = talus."},
/*107*/ {"q":"Sulphur granules contain:","o":["Staphylococcus aureus","Streptococcus","Actinomyces","Listeria","Nocardia"],"a":2,"e":"Sulphur granules (yellow/orange firm granules) are pathognomonic of Actinomyces israelii infection; seen in actinomycosis with chronic suppurative draining sinus tracts (cervicofacial, thoracic, abdominal).<br><br>Take Notes: Nocardia → acid-fast aerobic, weakly | Listeria → cold-loving | Actinomyces = sulphur granules."},
/*108*/ {"q":"A 30-year-old male is brought to the emergency department after a road traffic accident. He has a Glasgow Coma Scale (GCS) score of 7/15 and shows signs of significant blood loss. What is the most appropriate next immediate step in management?","o":["Assess pupils and shift to ICU","Perform endotracheal intubation","Transfuse blood immediately","Order urgent CT scan","IV fluid resuscitation"],"a":1,"e":"GCS ≤8 indicates the need for airway protection; endotracheal intubation must precede other interventions per ATLS guidelines (ABCDE approach). Airway is always the first priority.<br><br>Take Notes: ATLS = ABCDE order | Pupils assessed after airway | GCS <8 = intubate (airway first)."},
/*109*/ {"q":"How many valves are typically present in the great saphenous vein of the lower limb?","o":["8","10","15-20","20-25","30"],"a":2,"e":"The great saphenous vein contains approximately 15-20 valves along its course from medial malleolus to the saphenofemoral junction. These prevent retrograde flow against gravity in lower limb venous return.<br><br>Take Notes: SFJ valve → most important | Perforator valves → also present | GSV valves = 15-20 along course."},
/*110*/ {"q":"During tonsillectomy increased bleeding may be due to damage of which vessel?","o":["Inferior thyroid artery","Sphenopalatine artery","Brachiocephalic vein","Tonsillar artery","Lingual artery"],"a":3,"e":"The tonsillar artery (branch of facial artery) is the main blood supply to the palatine tonsil; bleeding during tonsillectomy commonly results from inadequate hemostasis of this vessel.<br><br>Take Notes: Inferior thyroid → thyroid surgery | Sphenopalatine → nasal | Tonsillectomy bleed = tonsillar artery."},
/*111*/ {"q":"A 65-year-old male with memory loss, personality changes, visual hallucinations and myoclonus. Most likely diagnosis?","o":["Alzheimer's disease","Alcohol-related dementia","Vascular dementia","Lewy body dementia","Frontotemporal dementia"],"a":3,"e":"Lewy body dementia: triad of fluctuating cognition, visual hallucinations, and parkinsonism; myoclonus and REM sleep behaviour disorder common. Alpha-synuclein protein aggregates (Lewy bodies) in cortex.<br><br>Take Notes: Alzheimer → memory predominant + tau/Aβ | Vascular → stepwise | Hallucinations + myoclonus = Lewy body."},
/*112*/ {"q":"On upper part of piriformis (suprapiriform), which one passes?","o":["Superior gluteal artery","Inferior gluteal artery","Inferior epigastric artery","Genital branch of genitofemoral nerve","Pudendal nerve"],"a":0,"e":"The suprapiriform foramen (above piriformis) transmits superior gluteal artery, vein, and nerve. Inferior gluteal, sciatic, pudendal, and posterior cutaneous nerves pass below piriformis (infrapiriform).<br><br>Take Notes: Below piriformis → inferior gluteal, sciatic, pudendal | Above piriformis = superior gluteal vessels + nerve."},
/*113*/ {"q":"Sciatic nerve damaged but flexion of knee is intact. Which structure is responsible?","o":["Popliteus","Sartorius","Gracilis","Biceps femoris short head","Quadriceps femoris"],"a":1,"e":"Sartorius is innervated by the femoral nerve (not sciatic) and flexes the knee. With sciatic injury, hamstrings (sciatic-innervated) are paralysed, but sartorius preserves some knee flexion.<br><br>Take Notes: Hamstrings → sciatic (paralysed) | Biceps femoris short head → also sciatic | Sciatic intact knee flexion = sartorius."},
/*114*/ {"q":"A 37-year-old pregnant woman presents for antenatal screening. Her husband has a family history of Down syndrome. Most appropriate next step to assess the risk of chromosomal abnormality in the fetus?","o":["Alpha-fetoprotein (AFP)","Serum β-hCG","Chorionic villus sampling (CVS)","Karyotyping of parents","Amniocentesis"],"a":1,"e":"For Down syndrome (trisomy 21) screening in 2nd trimester, low AFP and high β-hCG with low estriol comprise triple screen; first trimester combined screen uses PAPP-A and β-hCG with nuchal translucency.<br><br>Take Notes: AFP → NTD/Down screening | CVS/amnio → diagnostic if positive | Down screening = β-hCG (elevated)."},
/*115*/ {"q":"A 30-year-old woman presents with amenorrhea and milky nipple discharge. Urine β-hCG is negative. Most likely hormonal profile?","o":["Increased prolactin, decreased FSH, decreased LH","Decreased prolactin, decreased FSH, decreased LH","Increased prolactin, increased FSH, decreased LH","Decreased prolactin, increased FSH, increased LH","Normal prolactin, decreased FSH, normal LH"],"a":0,"e":"Prolactinoma: increased prolactin suppresses GnRH, leading to decreased FSH and LH causing secondary amenorrhea, infertility, and galactorrhea. Most common functioning pituitary adenoma.<br><br>Take Notes: PCOS → high LH/FSH ratio | Menopause → high FSH/LH, low estrogen | Amenorrhea + galactorrhea = high PRL, low FSH/LH."},
/*116*/ {"q":"A 50-year-old woman with hot flashes, dry skin, irritability, and absence of menstruation for 8 months. What is the most likely cause?","o":["Menopause","Hyperthyroidism","Premature ovarian failure","Chronic stress","Pregnancy"],"a":0,"e":"Menopause: cessation of menstruation for 12 months in middle-aged women due to ovarian follicle depletion; presents with vasomotor symptoms (hot flashes), genitourinary atrophy, mood changes, and bone loss.<br><br>Take Notes: Premature ovarian failure → <40 years | Hyperthyroidism → systemic | 50yo + hot flashes + amenorrhea = menopause."},
/*117*/ {"q":"Male with CHF presents with gradual loss of near vision. Damage is in:","o":["Midbrain","Medulla","Cerebrum","Basal ganglia","Pons"],"a":0,"e":"Near vision (accommodation) is controlled by Edinger-Westphal nucleus in midbrain via CN III parasympathetic fibers; midbrain damage impairs accommodation reflex and pupillary constriction.<br><br>Take Notes: Pons → CN V, VI, VII nuclei | Medulla → CN IX-XII | Accommodation = midbrain (Edinger-Westphal)."},
/*118*/ {"q":"A 25-year-old male falls on his elbow and sustains a fracture of the medial epicondyle of the humerus. He presents with numbness and tingling along the medial side of the hand. Which loss is most likely?","o":["Loss of sensation over the lateral side of the palmar aspect of the hand","Loss of sensation over the dorsal side of the lateral side of the hand","Loss of sensation over the lateral and posterior aspects of the hand","Loss of sensation over 1½ fingers and medial side of palm and dorsum","Loss of sensation over the entire hand"],"a":3,"e":"Ulnar nerve passes behind medial epicondyle and is vulnerable to fracture there; supplies medial 1½ fingers (little + half of ring) and medial side of palm and dorsum. Sensory loss reflects this.<br><br>Take Notes: Median → lateral 3.5 fingers | Radial → posterior arm/forearm strip | Medial epicondyle = ulnar nerve."},
/*119*/ {"q":"Between which vertebrae does sacralization most commonly occur?","o":["L5 and S1","L4 and L5","L3 and L4","L2 and L3","L1 and L2"],"a":0,"e":"Sacralization is the abnormal fusion of L5 with S1 (lumbar vertebra becoming part of sacrum); congenital anomaly, may cause back pain. Conversely, lumbarization is S1 separating from sacrum.<br><br>Take Notes: Lumbarization → S1 → separate (becomes \"L6\") | Sacralization = L5 fuses with S1."},
/*120*/ {"q":"A female patient delivered a baby. Bay has tuft of hair on back. Mother was taking diet rich in proteins and carbohydrates but deficient in fruits and vegetables. What is the reason of this condition?","o":["Iron deficiency","Folic acid deficiency","Vitamin B12 deficiency","Vitamin K deficiency","Vitamin E deficiency"],"a":1,"e":"Spina bifida (tuft of hair on lower back) is a neural tube defect; folic acid deficiency in early pregnancy is the major cause. Daily 400 mcg supplementation prevents NTDs.<br><br>Take Notes: B12 → also NTD link but rarer | Iron → microcytic anemia | NTD with tuft of hair = folic acid deficiency."},
/*121*/ {"q":"A 29-year-old pregnant woman has been diagnosed with thalassemia minor. She is concerned about the risk of her baby inheriting a severe form of the disease. What is the most appropriate next step to assess fetal status during pregnancy?","o":["Chorionic villus sampling (CVS)","Amniocentesis","Maternal blood smear","Hemoglobin electrophoresis after birth","Routine ultrasound"],"a":0,"e":"Chorionic villus sampling (CVS) at 10-13 weeks gestation allows early prenatal diagnosis of thalassemia via DNA analysis. Amniocentesis is alternative at 15-20 weeks but later. CVS allows earlier intervention.<br><br>Take Notes: Amniocentesis → 15-20 weeks | CVS → 10-13 weeks (earlier) | Early fetal genetic testing = CVS."},
/*122*/ {"q":"A 12-year-old boy presents with body swelling and proteinuria >10 g/day. Laboratory investigations reveal hypoalbuminemia. What is the primary mechanism responsible for edema in this patient?","o":["Decreased oncotic pressure","Increased capillary hydrostatic pressure","Lymphatic obstruction","Sodium and water retention","Vascular permeability"],"a":0,"e":"Nephrotic syndrome: massive proteinuria (>3.5 g/day) leads to hypoalbuminemia and decreased plasma oncotic pressure; fluid moves into interstitium causing generalized edema (periorbital, dependent).<br><br>Take Notes: Cardiac edema → increased hydrostatic | Lymphedema → obstruction | Nephrotic edema = decreased oncotic pressure."},
/*123*/ {"q":"A 28-year-old pregnant woman with complaints of fatigue, pallor, and generalized weakness. On questioning, she reports she has not been taking folic acid supplements during pregnancy. What type of anemia is most likely in this patient?","o":["Megaloblastic anemia","Iron deficiency anemia","Aplastic anemia","Hemolytic anemia","Sickle cell anemia"],"a":0,"e":"Pregnancy increases folate demand; deficient supplementation leads to megaloblastic anemia (macrocytic, hypersegmented neutrophils). Pregnancy folate deficiency also risks neural tube defects in fetus.<br><br>Take Notes: Iron deficiency → microcytic | Aplastic → pancytopenia | Pregnancy + no folate = megaloblastic anemia."},
/*124*/ {"q":"A 30-year-old female presents with fatigue and muscle weakness that worsens in the evening. She also reports difficulty in chewing and bilateral ptosis. Most likely diagnosis?","o":["Myasthenia gravis","Multiple sclerosis","Guillain-Barré syndrome","Lambert-Eaton syndrome","Polymyositis"],"a":0,"e":"Myasthenia gravis: fluctuating muscle weakness that worsens with use (fatigability) and improves with rest. Ocular (ptosis, diplopia), bulbar (chewing, swallowing), and limb weakness. Anti-AChR antibodies.<br><br>Take Notes: Lambert-Eaton → improves with use | MS → CNS demyelination | Fatigability + ptosis = myasthenia gravis."},
/*125*/ {"q":"A 16-year-old boy presents with a gunshot wound at the level of the 9th intercostal space on the right side. Which organ is most likely to be injured?","o":["Liver","Head of pancreas","Spleen","Right kidney","Right suprarenal gland"],"a":0,"e":"Right 9th intercostal space corresponds to the liver: the largest abdominal organ, occupies right hypochondrium and extends to right lumbar region. Most commonly injured by lower right chest trauma.<br><br>Take Notes: Spleen → left side trauma | Pancreas → midline retroperitoneal | Right 9th ICS trauma = liver."},
/*126*/ {"q":"A tall boy with thin, long fingers presents with increased pulse pressure and a femoral bruit. Examination reveals a water hammer pulse at the radial artery. Auscultation identifies a mid-diastolic along with a mitral systolic murmur. What is the most likely cardiac defect?","o":["Myocarditis","Aortic regurgitation","Mitral regurgitation","Aortic stenosis","Tricuspid stenosis"],"a":1,"e":"Marfan syndrome (tall, thin fingers, arachnodactyly) with aortic root dilation causes aortic regurgitation: wide pulse pressure, water hammer pulse, Austin-Flint murmur (mid-diastolic from regurgitant jet on mitral valve).<br><br>Take Notes: Aortic stenosis → narrow pulse pressure | Austin-Flint = AR + functional mitral murmur | Marfan + AR features = aortic regurgitation."},
/*127*/ {"q":"A person with a history of smoking and drinking from many years presents on endoscopy with a mass in middle third of esophagus. What could it likely be?","o":["Adenocarcinoma","Squamous cell carcinoma","Barret's esophagus","Chronic esophagitis","Gastritis"],"a":1,"e":"Squamous cell carcinoma is the most common esophageal cancer worldwide, classically in upper and middle third of esophagus. Strongly associated with smoking, alcohol, and hot beverages. Adenocarcinoma involves lower third.<br><br>Take Notes: Adenocarcinoma → lower 1/3 from Barret's | Upper/middle 1/3 + smoking/alcohol = SCC."},
/*128*/ {"q":"A 45-year-old male presents to the emergency department with hematemesis and malena. His vital signs are stable. What is the most appropriate next step in the evaluation and management of this patient?","o":["Upper gastrointestinal (GI) endoscopy","MRCP","CT scan of the abdomen","Abdominal X-ray","Abdominal ultrasound (USG)"],"a":0,"e":"Upper GI bleeding (hematemesis + melena) requires urgent endoscopy after stabilization; identifies source, allows therapeutic intervention (banding, clips, injection), and risk stratifies. Top diagnostic and therapeutic tool.<br><br>Take Notes: MRCP → biliary | CT → after endoscopy if needed | UGI bleed evaluation = endoscopy."},
/*129*/ {"q":"A 1-year-old baby presents with colicky abdominal pain, diarrhea, and passage of blood-stained stool. His diaper appears to be stained with red currant jelly-like material. What is the most likely diagnosis?","o":["Meckel's diverticulum","Intussusception","Intestinal obstruction","Hirschsprung disease","Volvulus"],"a":1,"e":"Intussusception in infants: classic triad — colicky abdominal pain, sausage-shaped mass (palpable in RUQ), and red currant jelly stools. Most common abdominal emergency in 6-36 months age group. Ileocolic typical.<br><br>Take Notes: Meckel → painless bleeding | Hirschsprung → constipation | Currant jelly stool = intussusception."},
/*130*/ {"q":"A patient presents with a right groin swelling located lateral and inferior to the pubic tubercle. Most likely diagnosis?","o":["Hydrocele","Indirect hernia","Femoral hernia","Varicocele","Direct hernia"],"a":2,"e":"Femoral hernia: lateral and inferior to pubic tubercle (vs. inguinal which is medial and superior). More common in females; high strangulation risk due to narrow femoral canal. Emergency surgery often needed.<br><br>Take Notes: Inguinal hernia → medial + superior to PT | Hydrocele → scrotal | Lateral + inferior to PT = femoral hernia."},
/*131*/ {"q":"A 38-year-old multiparous woman (Para 9) presents with a soft, reducible swelling around the umbilicus that increases on coughing. She has no previous abdominal surgery. What is the most likely diagnosis?","o":["Umbilical hernia","Paraumbilical hernia","Incisional hernia","Epigastric hernia","Femoral hernia"],"a":1,"e":"Paraumbilical hernia: defect just lateral to umbilicus (typically supra- or infra-umbilical), common in middle-aged multiparous women with raised intra-abdominal pressure. Distinct from true umbilical hernia (through umbilicus).<br><br>Take Notes: Umbilical → infants (through umbilicus) | Incisional → previous surgery | Multipara + periumbilical = paraumbilical."},
/*132*/ {"q":"Most common site of ulceration at stomach:","o":["Antrum of stomach","Pylorus of stomach","Lesser curvature","Greater curvature","Fundus of stomach"],"a":2,"e":"Lesser curvature of stomach is the most common site of gastric ulcers; commonly at the angularis incisura. Gastric ulcers cause pain after meals (vs duodenal which is relieved by food).<br><br>Take Notes: Duodenal ulcer → first part most common | Antrum → also common site | Gastric ulcer = lesser curvature."},
/*133*/ {"q":"What is the main arterial supply to the middle one-third of the esophagus?","o":["Inferior thyroid artery","Bronchial arteries","Esophageal branches of the aorta","Left gastric artery","Phrenic arteries"],"a":2,"e":"Middle third of esophagus is supplied by esophageal branches directly from descending thoracic aorta. Upper third gets inferior thyroid artery; lower third gets left gastric and inferior phrenic arteries.<br><br>Take Notes: Upper 1/3 → inferior thyroid | Lower 1/3 → left gastric | Middle 1/3 = aortic branches."},
/*134*/ {"q":"Most common cause of rheumatic fever:","o":["Group A β-hemolytic streptococcus","Group B streptococcus","Staphylococcus aureus","Streptococcus pneumoniae","Group D streptococcus"],"a":0,"e":"Rheumatic fever follows pharyngitis caused by Group A β-hemolytic streptococcus (Strep. pyogenes); 1-3 weeks after infection. Molecular mimicry between bacterial M protein and host antigens causes immune cross-reaction.<br><br>Take Notes: Group B → neonatal sepsis | Pneumoniae → pneumonia | Rheumatic fever = Group A strep (pyogenes)."},
/*135*/ {"q":"A 36-year-old female undergoes pelvic surgery for an ovarian mass. During the procedure, the ovary is found adherent to the posterior pelvic wall and is removed. Which structure is most at risk of injury during this dissection?","o":["Ureter","External iliac artery","Internal pudendal nerve","Round ligament of uterus","Ovarian ligament"],"a":0,"e":"The ureter passes close to the ovarian vessels and ovary in the pelvis (\"water under the bridge\" - uterine artery crosses ureter); at risk during ovarian surgery, especially with adherent masses.<br><br>Take Notes: External iliac → more lateral | Internal pudendal → pelvic floor | Ovarian surgery = ureter at risk."},
/*136*/ {"q":"A 5-year-old child is diagnosed with hydrocephalus localized to the right lateral ventricle. MRI shows enlargement of the right lateral ventricle only, with normal third and fourth ventricles. Which structure is most likely obstructed?","o":["Aqueduct of Sylvius","Foramina of Monro","Foramina of Luschka","Foramen of Magendie","Central canal of the spinal cord"],"a":1,"e":"Foramen of Monro connects each lateral ventricle to the third ventricle; obstruction causes isolated lateral ventricle dilatation. Bilateral foramina of Monro obstruction would dilate both lateral ventricles.<br><br>Take Notes: Aqueduct of Sylvius → 3rd + 4th vent | Luschka/Magendie → 4th → subarachnoid | One lateral vent enlarged = foramen of Monro."},
/*137*/ {"q":"Why does carbamazepine reduce nifedipine's effect?","o":["It induces cytochrome P450","Decreases absorption","Blocks receptors","Reduces renal excretion","Inhibits hepatic metabolism"],"a":0,"e":"Carbamazepine is a potent CYP3A4 (and 2C9) inducer; accelerates hepatic metabolism of nifedipine (CYP3A4 substrate), reducing its plasma concentration and clinical effect. Classic drug interaction.<br><br>Take Notes: P450 inducers → phenytoin, rifampicin, carbamazepine | Nifedipine = CYP3A4 substrate | CBZ + nifedipine = induced metabolism."},
/*138*/ {"q":"A 30-year-old female presents with weight loss, palpitations, heat intolerance, and tremors. She is diagnosed with hyperthyroidism. Which of the following medications is used as an adjunct treatment to control symptoms until definitive therapy takes effect?","o":["Propranolol","Methimazole","Levothyroxine","Prednisolone","Iodine 131"],"a":0,"e":"Propranolol (non-selective β-blocker) provides rapid symptom relief in hyperthyroidism by blocking adrenergic effects (palpitations, tremor, heat intolerance) while waiting for thionamides or definitive therapy.<br><br>Take Notes: Methimazole → primary thionamide (slow onset) | Iodine 131 → definitive ablation | Symptomatic adjunct = propranolol."},
/*139*/ {"q":"Atherosclerotic plaque has which 3 principal components?","o":["Smooth muscle, T cells, neutrophils","Smooth muscle, lymphocytes","Lymphocytes only","Smooth muscle, macrophages, T cells with ECM and lipids","Foam cells and cholesterol clefts"],"a":3,"e":"Robbins triad of atherosclerotic plaque: cells (smooth muscle, macrophages/foam cells, T lymphocytes), extracellular matrix (collagen, elastic fibers, proteoglycans), and intra/extracellular lipids.<br><br>Take Notes: Foam cells = lipid-laden macrophages | 3 components = cells + ECM + lipids = Robbins."},
/*140*/ {"q":"Which of the following spinal cord tracts is primarily responsible for transmitting pain and temperature sensations to the brain?","o":["Lateral spinothalamic tract","Dorsal columns","Corticospinal tract","Spinocerebellar tract","Anterior corticospinal tract"],"a":0,"e":"Lateral spinothalamic tract transmits pain and temperature; fibers cross over at the spinal level of entry and ascend on the opposite side. Damage causes contralateral pain/temperature loss.<br><br>Take Notes: Dorsal columns → fine touch + proprioception (ipsilateral) | Corticospinal → motor | Pain + temperature = lateral spinothalamic."},
/*141*/ {"q":"Which of the following is a potent vasoconstrictor released by injured vascular endothelium to promote hemostasis?","o":["Prostaglandin I2","Vasopressin","Endothelin-1","Bradykinin","Nitric oxide"],"a":2,"e":"Endothelin-1 is a potent vasoconstrictor released by injured endothelial cells; promotes hemostasis through local vasoconstriction. Prostaglandin I2 and nitric oxide are vasodilators promoting vessel patency.<br><br>Take Notes: NO + PGI2 → vasodilator | Bradykinin → also vasodilator | Endothelial vasoconstrictor = endothelin-1."},
/*142*/ {"q":"Mechanism of action of gangrene caused by Clostridium perfringens:","o":["Local hypoxia","Release of phospholipase","Decreased ATP","Release of ACh","Toxin-mediated cytolysis"],"a":1,"e":"Clostridium perfringens alpha-toxin (phospholipase C / lecithinase) hydrolyses membrane phospholipids causing cell lysis; produces gas gangrene with crepitus, severe necrosis. Treatment: surgical debridement and penicillin.<br><br>Take Notes: Local hypoxia = predisposing factor | Cytolysis = consequence | C. perfringens MOA = phospholipase release."},
/*143*/ {"q":"A girl in the garden was plucking a flower when a thorn pricked her finger. She immediately withdrew her hand in response. Which sensory pathway is primarily responsible for this rapid withdrawal reflex?","o":["Neospinothalamic tract","Paleospinothalamic tract","Dorsal column-medial lemniscus pathway","Spinocerebellar tract","Reticulospinal tract"],"a":0,"e":"Neospinothalamic (lateral spinothalamic) tract carries fast, sharp, well-localised pain via Aδ fibers; mediates rapid withdrawal reflex. Paleospinothalamic carries slow, dull, poorly localised pain via C fibers.<br><br>Take Notes: Paleospinothalamic → slow burning pain (C fibers) | Dorsal column → discriminative touch | Sharp fast pain = neospinothalamic."},
/*144*/ {"q":"A 27-year-old female presents with a 2-day history of right upper quadrant abdominal pain and fever. On examination, Murphy's sign is positive. What is the next best investigation to confirm the diagnosis?","o":["ERCP","Abdominal ultrasound","Contrast-enhanced CT of abdomen","Complete blood count","MRCP"],"a":1,"e":"Acute cholecystitis (RUQ pain + fever + positive Murphy's sign): abdominal ultrasound is the initial investigation of choice — high sensitivity for gallstones, wall thickening, pericholecystic fluid, sonographic Murphy's sign.<br><br>Take Notes: ERCP → therapeutic for stones in CBD | CT → if USG inconclusive | Acute cholecystitis = ultrasound first."},
/*145*/ {"q":"A diabetic patient presents with a red, swollen, and painful lesion on his back. The lesion appears to be larger than a boil and has multiple pus-draining openings. What is the most likely diagnosis?","o":["Carbuncle","Furuncle","Folliculitis","Cellulitis","Abscess"],"a":0,"e":"Carbuncle: multi-loculated cluster of furuncles with several draining sinuses, common in diabetics; affects back of neck/upper back. Larger than single furuncle (boil), often Staphylococcus aureus etiology.<br><br>Take Notes: Furuncle = single boil | Folliculitis = superficial | Diabetic + multiple draining openings = carbuncle."},
/*146*/ {"q":"Glucose is primarily reabsorbed in which part of the nephron?","o":["Proximal convoluted tubule (PCT)","Distal convoluted tubule (DCT)","Collecting duct (CD)","Loop of Henle","Bowman's capsule"],"a":0,"e":"PCT reabsorbs ~99% of filtered glucose via SGLT2 (early PCT) and SGLT1 (late PCT) co-transporters with sodium. SGLT2 inhibitors (diabetes drugs) block this reabsorption causing glycosuria.<br><br>Take Notes: Loop of Henle → water/NaCl, not glucose | DCT → fine-tuning | Glucose reabsorption = PCT."},
/*147*/ {"q":"Hormonal therapy can lead to regression of hormone-sensitive tumor size through which of the following cellular processes?","o":["Metaplasia","Atrophy","Dysplasia","Carcinoma in situ","Apoptosis"],"a":4,"e":"Hormonal therapy in hormone-sensitive tumors (breast, prostate) blocks hormone signalling that promotes tumor cell survival; cells then undergo apoptosis (programmed cell death), reducing tumor size.<br><br>Take Notes: Atrophy → reduced cell size | Metaplasia → cell type change | Hormone deprivation tumor regression = apoptosis."},
/*148*/ {"q":"Vasculitis features with purpura on the buttocks in a child seen in which of these?","o":["HSP (Henoch-Schönlein purpura)","Arthritis","SLE","Sjögren syndrome","Polyarteritis nodosa"],"a":0,"e":"Henoch-Schönlein purpura (HSP): IgA vasculitis in children with classic tetrad — palpable purpura on buttocks/legs, abdominal pain, arthritis, and renal involvement (IgA nephropathy). Self-limiting in most cases.<br><br>Take Notes: SLE → multisystem ANA+ | PAN → adults, severe | Child + purpura on buttocks = HSP."},
/*149*/ {"q":"A man hears the sudden news of his father's death and immediately becomes unconscious. On arrival, the doctor diagnoses him with shock. Which best describes the underlying mechanism of this type of shock?","o":["Vasomotor failure","Cardiogenic shock","Hypovolemic shock","Neurogenic shock","Vasodilation"],"a":0,"e":"Neurogenic/vasovagal shock from emotional stress: sudden parasympathetic surge and sympathetic withdrawal cause vasomotor failure with massive vasodilation, bradycardia, and reduced cerebral perfusion leading to syncope.<br><br>Take Notes: Cardiogenic → pump failure | Hypovolemic → fluid loss | Sudden news syncope = vasomotor failure (neurogenic)."},
/*150*/ {"q":"Which type of nerve fibers are carried by the dorsal root ganglion?","o":["Motor fibers","Sensory fibers","Sympathetic fibers","Parasympathetic fibers","Mixed fibers"],"a":1,"e":"Dorsal root ganglion contains cell bodies of primary sensory (afferent) neurons; carries somatic and visceral sensory fibers to the spinal cord. Ventral root contains motor (efferent) fibers.<br><br>Take Notes: Ventral root → motor | Autonomic → sympathetic chain ganglia separately | Dorsal root ganglion = sensory."},
/*151*/ {"q":"A middle aged male patient presents with obesity (BMI 38), elevated lipid levels, abdominal striae, and newly diagnosed diabetes mellitus. What is the most likely underlying cause of his obesity?","o":["Hypothalamic damage","Type 2 diabetes mellitus","Leptin deficiency","Cushing's syndrome","Abdominal carcinoma"],"a":3,"e":"Cushing syndrome: central obesity, abdominal striae (purple), buffalo hump, moon face, and steroid diabetes mellitus from cortisol excess. Diagnosed by 24h urine cortisol or dexamethasone suppression test.<br><br>Take Notes: Hypothalamic obesity → rare | Leptin def → genetic | Central obesity + striae + DM = Cushing syndrome."},
/*152*/ {"q":"Down syndrome child has double bubble sign due to:","o":["Duodenal atresia","Gastric outlet obstruction","Jejunal atresia","Hypertrophic pyloric sphincter","Malrotation"],"a":0,"e":"Duodenal atresia is strongly associated with Down syndrome (30% of cases); presents with bilious vomiting within first 24 hours and pathognomonic \"double bubble\" sign on X-ray (distended stomach + duodenum).<br><br>Take Notes: Jejunal atresia → multiple bubbles | Pyloric stenosis → projectile vomiting in older infant | Double bubble + Down = duodenal atresia."},
/*153*/ {"q":"A 40-year-old male from an endemic region presents with numbness and disfiguring skin lesions on his hands and face. He reports loss of sensation in the affected areas and difficulty closing his eyes. Examination reveals thickened nerves and hypopigmented patches. Most likely diagnosis?","o":["Tuberculosis","Hansen's disease","Syphilis","Lupus erythematosus","Sarcoidosis"],"a":1,"e":"Hansen disease (leprosy): Mycobacterium leprae infection causing peripheral nerve thickening, hypopigmented anaesthetic skin patches, and disfiguring lesions. Lagophthalmos (inability to close eyes) from facial nerve involvement.<br><br>Take Notes: TB → caseating granuloma, pulmonary | Syphilis → gummas + serology | Thickened nerves + anaesthetic patches = leprosy."},
/*154*/ {"q":"Coagulative necrosis is seen in:","o":["Brain","Kidney","Heart","TB","Pancreas"],"a":2,"e":"Coagulative necrosis is characteristic of myocardial infarction: tissue architecture preserved with loss of cellular detail (anucleate cells, eosinophilic cytoplasm). Most common in heart, kidney, spleen — ischemic infarct pattern.<br><br>Take Notes: Brain → liquefactive necrosis | TB → caseous necrosis | Pancreas → fat necrosis | Heart MI = coagulative."},
];
